  "FINISH BEFORE DELETING": ["FINISH BEFORE DELETING","VOR DEM LÖSCHEN ABSCHLIESSEN","TERMINAR ANTES DE ELIMINAR","VOLTOOIEN VOOR VERWIJDEREN","COMPLETA PRIMA DI ELIMINARE","TERMINER AVANT DE SUPPRIMER"],
  "{count} equipment crafts are still linked to this character.": ["{count} equipment crafts are still linked to this character.","Noch mit diesem Charakter verknüpfte Herstellungsaufträge: {count}.","Fabricaciones de equipo aún vinculadas a este personaje: {count}.","Nog aan dit personage gekoppelde uitrustingsopdrachten: {count}.","Creazioni equipaggiamento ancora collegate al personaggio: {count}.","Fabrications d'équipement encore liées à ce personnage : {count}."],
  "Type {confirmation} to unlock the delete actions.": ["Type {confirmation} to unlock the delete actions.","Gib {confirmation} ein, um die Löschaktionen freizuschalten.","Escribe {confirmation} para habilitar la eliminación.","Typ {confirmation} om verwijderen te ontgrendelen.","Digita {confirmation} per sbloccare l'eliminazione.","Saisissez {confirmation} pour autoriser la suppression."],
  "Character deletion confirmation": ["Character deletion confirmation","Bestätigung der Charakterlöschung","Confirmación de eliminación de personaje","Bevestiging personage verwijderen","Conferma eliminazione personaggio","Confirmation de suppression du personnage"],
