export type AccountKey=keyof typeof accountTranslationRows;
const languages:readonly Language[]=['en','de','es','nl','it','fr'];
export const accountCatalogs=Object.fromEntries(languages.map((language,index)=>[
  language,Object.fromEntries(Object.entries(accountTranslationRows).map(([key,row])=>[key,row[index]])),
])) as Record<Language,Record<AccountKey,string>>;
export const accountT=createTranslator<AccountKey>(accountCatalogs);

const templates=(Object.keys(accountTranslationRows) as AccountKey[]).filter(key=>key.includes('{')).sort((a,b)=>b.length-a.length).map(key=>{
  const names:string[]=[];
  const parts=key.split(/(\{[A-Za-z]+\})/g).map(part=>{
    if(/^\{[A-Za-z]+\}$/.test(part)){const name=part.slice(1,-1);names.push(name);return ['count','amount','percent','level','slot','day','cycle','hours','base','free','max','capacity','total','claimed','chapter','scale','step'].includes(name)?'([0-9][0-9.,+ ]*)':'(.+?)';}
    return part.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  });
  return {key,names,pattern:new RegExp('^'+parts.join('')+'$')};
});

/** Only call for application-owned presentation strings, never player-authored text. */
export function accountText(language:Language,text:string,params?:Record<string,string|number>):string{
  if(Object.prototype.hasOwnProperty.call(accountTranslationRows,text))return accountT(language,text as AccountKey,params);
  if(language==='en')return text;
  const normalized=text
    .replace(/^\+1 saved loadout$/,'+1 saved loadouts')
    .replace(/^1 reward stack is waiting\./,'1 reward stacks are waiting.')
    .replace(/^Only 1 carried food portion remains\./,'Only 1 carried food portions remain.')
    .replace(/^(Reach character level \d+ · 1) level remaining\./,'$1 levels remaining.');
  for(const {key,names,pattern} of templates){
    const match=pattern.exec(normalized);if(!match)continue;
    const values=Object.fromEntries(names.map((name,index)=>[name,match[index+1]]));
    // These core templates contain known UI labels; names and other captures stay verbatim.
    for(const name of ['boost','source'])if(values[name])values[name]=accountText(language,values[name]);
    if(key==='Collection · {target}')values.target=accountText(language,values.target);
    return accountT(language,key,values);
  }
  return text;
}

export function accountError(language:Language,error:unknown,fallback:AccountKey='The request could not be completed. Please try again.'):string{
  const message=error instanceof Error?error.message:typeof error==='string'?error:'';
  if(Object.prototype.hasOwnProperty.call(accountTranslationRows,message)||templates.some(({pattern})=>pattern.test(message)))return accountText(language,message);
  // Unknown server/native errors have no translation contract; show a localized actionable fallback.
  return accountT(language,fallback);
}

export function accountDuration(language:Language,seconds:number):string{
  const total=Math.max(0,Math.floor(seconds)),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60),rest=total%60;
  const hour={en:'h',de:'Std.',es:'h',nl:'u',it:'h',fr:'h'}[language];
  const minute={en:'m',de:'Min.',es:'min',nl:'min',it:'min',fr:'min'}[language];
  const second={en:'s',de:'Sek.',es:'s',nl:'s',it:'s',fr:'s'}[language];
  return hours?`${hours} ${hour} ${minutes} ${minute}`:minutes?`${minutes} ${minute} ${rest} ${second}`:`${rest} ${second}`;
}
